fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of input rows
    let rows = arr.len();
    // Number of input columns (assume at least one row)
    let cols = arr[0].len();

    // Build the transposed matrix: cols x rows
    (0..cols)
        .map(|j| {
            // For each new row j, collect the j-th element from each original row
            let mut new_row = Vec::with_capacity(rows);
            for i in 0..rows {
                new_row.push(arr[i][j]);
            }
            new_row
        })
        .collect()
}

